PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE settings (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL
);
CREATE TABLE players (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  melee_name TEXT,
  email TEXT,
  active INTEGER DEFAULT 1
);
CREATE TABLE leaders (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  "set" TEXT,
  active INTEGER DEFAULT 1
);
CREATE TABLE seasons (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  created_date TEXT
);
CREATE TABLE leader_votes (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  timestamp TEXT NOT NULL,
  season_id INTEGER NOT NULL,
  week INTEGER NOT NULL,
  player_id TEXT NOT NULL,
  leader_id TEXT NOT NULL,
  FOREIGN KEY (season_id) REFERENCES seasons(id),
  FOREIGN KEY (player_id) REFERENCES players(id),
  FOREIGN KEY (leader_id) REFERENCES leaders(id),
  UNIQUE(season_id, week, player_id)
);
CREATE TABLE opponent_votes (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  timestamp TEXT NOT NULL,
  season_id INTEGER NOT NULL,
  week INTEGER NOT NULL,
  opponent_id TEXT NOT NULL,
  FOREIGN KEY (season_id) REFERENCES seasons(id),
  FOREIGN KEY (opponent_id) REFERENCES players(id)
);
CREATE TABLE awards (
  season_id INTEGER NOT NULL,
  award_name TEXT NOT NULL,
  player_id TEXT NOT NULL,
  score REAL,
  PRIMARY KEY (season_id, award_name, player_id),
  FOREIGN KEY (season_id) REFERENCES seasons(id),
  FOREIGN KEY (player_id) REFERENCES players(id)
);
CREATE TABLE attendance (
  season_id INTEGER NOT NULL,
  week INTEGER NOT NULL,
  player_id TEXT NOT NULL,
  FOREIGN KEY (season_id) REFERENCES seasons(id),
  FOREIGN KEY (player_id) REFERENCES players(id),
  PRIMARY KEY (season_id, week, player_id)
);
CREATE TABLE IF NOT EXISTS "sessions" (
  token TEXT PRIMARY KEY,
  player_id TEXT NOT NULL,
  device_id TEXT NOT NULL,
  email TEXT,
  created TEXT NOT NULL,
  last_active TEXT NOT NULL,
  FOREIGN KEY (player_id) REFERENCES players(id),
  UNIQUE(player_id, device_id)
);
CREATE TABLE melee_tournaments (
  melee_id INTEGER PRIMARY KEY,
  season_id INTEGER NOT NULL,
  round INTEGER NOT NULL,
  name TEXT NOT NULL,
  date TEXT,
  FOREIGN KEY (season_id) REFERENCES seasons(id)
);
CREATE TABLE season_standings (
  season_id INTEGER NOT NULL,
  round INTEGER NOT NULL,
  player_id TEXT NOT NULL,
  wins INTEGER DEFAULT 0,
  losses INTEGER DEFAULT 0,
  draws INTEGER DEFAULT 0,
  match_points INTEGER DEFAULT 0,
  rank INTEGER,
  PRIMARY KEY (season_id, round, player_id),
  FOREIGN KEY (season_id) REFERENCES seasons(id),
  FOREIGN KEY (player_id) REFERENCES players(id)
);
CREATE TABLE match_results (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  season_id INTEGER NOT NULL,
  round INTEGER NOT NULL,
  melee_match_id INTEGER,
  player1_id TEXT NOT NULL,
  player2_id TEXT NOT NULL,
  winner_id TEXT,
  result TEXT, is_bye INTEGER DEFAULT 0,
  FOREIGN KEY (season_id) REFERENCES seasons(id),
  FOREIGN KEY (player1_id) REFERENCES players(id),
  FOREIGN KEY (player2_id) REFERENCES players(id)
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_leader_votes_season_week ON leader_votes(season_id, week);
CREATE INDEX idx_leader_votes_player ON leader_votes(player_id);
CREATE INDEX idx_opponent_votes_season_week ON opponent_votes(season_id, week);
CREATE INDEX idx_attendance_season ON attendance(season_id, week);
CREATE INDEX idx_sessions_player ON sessions(player_id);
CREATE INDEX idx_sessions_device ON sessions(device_id);
CREATE INDEX idx_attendance_season_player ON attendance(season_id, player_id);
CREATE INDEX idx_melee_tournaments_season ON melee_tournaments(season_id);
CREATE INDEX idx_season_standings_season ON season_standings(season_id, round);
CREATE INDEX idx_match_results_season ON match_results(season_id, round);
